CREATE TABLE tenant(id uuid PRIMARY KEY, name text NOT NULL);
CREATE TABLE membership(username text PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenant,role text NOT NULL CHECK(role IN ('ADMIN','OPERATIONS','WAREHOUSE','FINANCE')));
CREATE TABLE sku(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenant,code text NOT NULL,name text NOT NULL,cost numeric(19,4) NOT NULL CHECK(cost>=0),UNIQUE(tenant_id,code),UNIQUE(tenant_id,id));
CREATE TABLE inventory(tenant_id uuid NOT NULL,sku_id uuid NOT NULL,on_hand integer NOT NULL CHECK(on_hand>=0),reserved integer NOT NULL DEFAULT 0 CHECK(reserved>=0 AND reserved<=on_hand),PRIMARY KEY(tenant_id,sku_id),FOREIGN KEY(tenant_id,sku_id) REFERENCES sku(tenant_id,id));
CREATE TABLE sales_order(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenant,store text NOT NULL,external_id text NOT NULL,status text NOT NULL DEFAULT 'NEW',net numeric(19,4) NOT NULL,rate numeric(19,8) NOT NULL,currency text NOT NULL,rate_source text NOT NULL,rate_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,store,external_id),UNIQUE(tenant_id,id));
CREATE TABLE order_item(tenant_id uuid NOT NULL,order_id uuid NOT NULL,sku_id uuid NOT NULL,quantity integer NOT NULL CHECK(quantity>0),PRIMARY KEY(order_id,sku_id),FOREIGN KEY(tenant_id,order_id) REFERENCES sales_order(tenant_id,id),FOREIGN KEY(tenant_id,sku_id) REFERENCES sku(tenant_id,id));
CREATE TABLE inventory_movement(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,order_id uuid NOT NULL,sku_id uuid NOT NULL,kind text NOT NULL,quantity integer NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(order_id,sku_id,kind));
